#include <bits/stdc++.h>
using namespace std;

vector<string> split(const string &s) {
    vector<string> parts;
    string cur;
    stringstream in(s);
    while (getline(in, cur, ',')) parts.push_back(cur);
    return parts;
}

string strip(const string &s) {
    size_t a = s.find_first_not_of(" \t\r\n"), b = s.find_last_not_of(" \t\r\n");
    return a == string::npos ? "" : s.substr(a, b - a + 1);
}

int main() {
    vector<string> lines;
    for (string line; getline(cin, line);) {
        line = strip(line);
        if (!line.empty()) lines.push_back(line);
    }
    size_t cur = 0;
    int n = stoi(lines[cur++]);
    vector<string> merchant(n), customer(n);
    vector<long long> amount(n);
    vector<int> hour(n);
    for (int i = 0; i < n; i++) {
        auto p = split(lines[cur++]);
        merchant[i] = p[0]; amount[i] = stoll(p[1]); customer[i] = p[2]; hour[i] = stoi(p[3]);
    }
    vector<array<long long, 4>> rules(n);
    for (int i = 0; i < n; i++) {
        auto p = split(lines[cur++]);
        for (int j = 0; j < 4; j++) rules[i][j] = stoll(p[j]);
    }
    int m = stoi(lines[cur++]);
    map<string, long long> scores;
    for (int i = 0; i < m; i++) {
        auto p = split(lines[cur++]);
        scores[p[0]] = stoll(p[1]);
    }
    // Pass 1: amount multipliers (strictly greater than the threshold).
    for (int i = 0; i < n; i++)
        if (amount[i] > rules[i][0]) scores[merchant[i]] *= rules[i][1];
    // Pass 2: a (merchant, customer) group with at least 3 transactions adds every additive factor.
    map<pair<string, string>, vector<int>> lifetime;
    for (int i = 0; i < n; i++) lifetime[{merchant[i], customer[i]}].push_back(i);
    for (auto &[key, idx] : lifetime)
        if (idx.size() >= 3)
            for (int i : idx) scores[key.first] += rules[i][2];
    // Pass 3: same-hour groups of at least 3 apply penalties by the hour band.
    map<tuple<string, string, int>, vector<int>> perHour;
    for (int i = 0; i < n; i++) perHour[{merchant[i], customer[i], hour[i]}].push_back(i);
    for (auto &[key, idx] : perHour) {
        if (idx.size() < 3) continue;
        long long total = 0;
        for (int i : idx) total += rules[i][3];
        int h = get<2>(key);
        if (12 <= h && h <= 17) scores[get<0>(key)] += total;
        else if ((9 <= h && h <= 11) || (18 <= h && h <= 21)) scores[get<0>(key)] -= total;
    }
    string out = to_string(scores.size()) + "\n";
    for (auto &[k, v] : scores) out += k + "," + to_string(v) + "\n";
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        for (String line; (line = br.readLine()) != null;) {
            line = line.strip();
            if (!line.isEmpty()) lines.add(line);
        }
        int cur = 0;
        int n = Integer.parseInt(lines.get(cur++));
        String[] merchant = new String[n], customer = new String[n];
        long[] amount = new long[n];
        int[] hour = new int[n];
        for (int i = 0; i < n; i++) {
            String[] p = lines.get(cur++).split(",", -1);
            merchant[i] = p[0]; amount[i] = Long.parseLong(p[1].strip()); customer[i] = p[2]; hour[i] = Integer.parseInt(p[3].strip());
        }
        long[][] rules = new long[n][4];
        for (int i = 0; i < n; i++) {
            String[] p = lines.get(cur++).split(",", -1);
            for (int j = 0; j < 4; j++) rules[i][j] = Long.parseLong(p[j].strip());
        }
        int m = Integer.parseInt(lines.get(cur++));
        TreeMap<String, Long> scores = new TreeMap<>();
        for (int i = 0; i < m; i++) {
            String[] p = lines.get(cur++).split(",", -1);
            scores.put(p[0], Long.parseLong(p[1].strip()));
        }
        // Pass 1: amount multipliers (strictly greater than the threshold).
        for (int i = 0; i < n; i++)
            if (amount[i] > rules[i][0]) scores.put(merchant[i], scores.get(merchant[i]) * rules[i][1]);
        // Pass 2: a (merchant, customer) group with at least 3 transactions adds every additive factor.
        Map<List<String>, List<Integer>> lifetime = new HashMap<>();
        for (int i = 0; i < n; i++) lifetime.computeIfAbsent(List.of(merchant[i], customer[i]), k -> new ArrayList<>()).add(i);
        for (Map.Entry<List<String>, List<Integer>> e : lifetime.entrySet()) {
            if (e.getValue().size() < 3) continue;
            String mid = e.getKey().get(0);
            for (int i : e.getValue()) scores.put(mid, scores.get(mid) + rules[i][2]);
        }
        // Pass 3: same-hour groups of at least 3 apply penalties by the hour band.
        Map<List<String>, List<Integer>> perHour = new HashMap<>();
        for (int i = 0; i < n; i++)
            perHour.computeIfAbsent(List.of(merchant[i], customer[i], String.valueOf(hour[i])), k -> new ArrayList<>()).add(i);
        for (Map.Entry<List<String>, List<Integer>> e : perHour.entrySet()) {
            if (e.getValue().size() < 3) continue;
            long total = 0;
            for (int i : e.getValue()) total += rules[i][3];
            String mid = e.getKey().get(0);
            int h = Integer.parseInt(e.getKey().get(2));
            if (12 <= h && h <= 17) scores.put(mid, scores.get(mid) + total);
            else if ((9 <= h && h <= 11) || (18 <= h && h <= 21)) scores.put(mid, scores.get(mid) - total);
        }
        StringBuilder sb = new StringBuilder();
        sb.append(scores.size()).append('\n');
        for (Map.Entry<String, Long> e : scores.entrySet()) sb.append(e.getKey()).append(',').append(e.getValue()).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
	"strings"
)

func num(s string) int64 { v, _ := strconv.ParseInt(strings.TrimSpace(s), 10, 64); return v }

type pairKey struct{ merchant, customer string }
type hourKey struct {
	merchant, customer string
	hour               int64
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	var lines []string
	for sc.Scan() {
		if t := strings.TrimSpace(sc.Text()); t != "" {
			lines = append(lines, t)
		}
	}
	cur := 0
	n := int(num(lines[cur]))
	cur++
	merchant, customer := make([]string, n), make([]string, n)
	amount, hour := make([]int64, n), make([]int64, n)
	for i := 0; i < n; i++ {
		p := strings.Split(lines[cur], ",")
		cur++
		merchant[i], amount[i], customer[i], hour[i] = p[0], num(p[1]), p[2], num(p[3])
	}
	rules := make([][4]int64, n)
	for i := 0; i < n; i++ {
		p := strings.Split(lines[cur], ",")
		cur++
		for j := 0; j < 4; j++ {
			rules[i][j] = num(p[j])
		}
	}
	m := int(num(lines[cur]))
	cur++
	scores := map[string]int64{}
	for i := 0; i < m; i++ {
		p := strings.Split(lines[cur], ",")
		cur++
		scores[p[0]] = num(p[1])
	}
	// Pass 1: amount multipliers (strictly greater than the threshold).
	for i := 0; i < n; i++ {
		if amount[i] > rules[i][0] {
			scores[merchant[i]] *= rules[i][1]
		}
	}
	// Pass 2: a (merchant, customer) group with at least 3 transactions adds every additive factor.
	lifetime := map[pairKey][]int{}
	for i := 0; i < n; i++ {
		k := pairKey{merchant[i], customer[i]}
		lifetime[k] = append(lifetime[k], i)
	}
	for k, idx := range lifetime {
		if len(idx) >= 3 {
			for _, i := range idx {
				scores[k.merchant] += rules[i][2]
			}
		}
	}
	// Pass 3: same-hour groups of at least 3 apply penalties by the hour band.
	perHour := map[hourKey][]int{}
	for i := 0; i < n; i++ {
		k := hourKey{merchant[i], customer[i], hour[i]}
		perHour[k] = append(perHour[k], i)
	}
	for k, idx := range perHour {
		if len(idx) < 3 {
			continue
		}
		var total int64
		for _, i := range idx {
			total += rules[i][3]
		}
		h := k.hour
		if 12 <= h && h <= 17 {
			scores[k.merchant] += total
		} else if (9 <= h && h <= 11) || (18 <= h && h <= 21) {
			scores[k.merchant] -= total
		}
	}
	names := make([]string, 0, len(scores))
	for k := range scores {
		names = append(names, k)
	}
	sort.Strings(names)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(len(names)) + "\n")
	for _, k := range names {
		w.WriteString(k + "," + strconv.FormatInt(scores[k], 10) + "\n")
	}
}
